import{c as e,Q as l,j as t,m as r}from"./chunks/framework.BPKcPtvA.js";const c=JSON.parse('{"title":"RO3 公开 GVG「巅峰对决」实机影片 百人规模战役登场","description":"RO3 首支 GVG 实机影片公开，呈现百人攻城战与多层策略对抗","frontmatter":{"title":"RO3 公开 GVG「巅峰对决」实机影片 百人规模战役登场","description":"RO3 首支 GVG 实机影片公开，呈现百人攻城战与多层策略对抗"},"headers":[],"relativePath":"news/gvg-gameplay-202510.md","filePath":"news/gvg-gameplay-202510.md","lastUpdated":1779114110000}'),i={name:"news/gvg-gameplay-202510.md"};function o(n,a,s,p,d,g){return l(),t("div",null,[...a[0]||(a[0]=[r('<h1 id="gvg「巅峰对决」实机影片公开" tabindex="-1">GVG「巅峰对决」实机影片公开 <a class="header-anchor" href="#gvg「巅峰对决」实机影片公开" aria-label="Permalink to &quot;GVG「巅峰对决」实机影片公开&quot;">​</a></h1><p>日期：2025-10-23</p><p>官方公开首支 GVG「巅峰对决」实机影片，呈现百人规模战疫与多层次策略对抗。</p><h2 id="核心玩法特色" tabindex="-1">核心玩法特色 <a class="header-anchor" href="#核心玩法特色" aria-label="Permalink to &quot;核心玩法特色&quot;">​</a></h2><ul><li><strong>百人攻城战</strong> — 两大公会极限对抗</li><li><strong>大型攻城器械</strong> — 攻城车、云梯等器械登场</li><li><strong>巨型机甲</strong> — 可驾驶巨型机甲参与战斗</li><li><strong>砲台系统</strong> — 灵活运用砲台进行攻防</li></ul><h2 id="首届共创议会" tabindex="-1">首届共创议会 <a class="header-anchor" href="#首届共创议会" aria-label="Permalink to &quot;首届共创议会&quot;">​</a></h2><p>官方于同期举办首屆共创议会，邀请玩家代表（议员）针对「公会联赛」与「巅峰对决」两大议题进行讨论。</p><h3 id="玩家建议与官方回应精选" tabindex="-1">玩家建议与官方回应精选 <a class="header-anchor" href="#玩家建议与官方回应精选" aria-label="Permalink to &quot;玩家建议与官方回应精选&quot;">​</a></h3><p><strong>公会联赛方面：</strong></p><ul><li>降低联赛频率 → OB 版本确认下调</li><li>增加更多公会技能与地图机制 → 持续开发中</li><li>增战场数据便长管理 → OB 版本会呈现更完善的版本</li></ul><p><strong>巅峰对决方面：</strong></p><ul><li>支援多公会混战 → 领地战包含多种模式</li><li>新增消耗品 → 列入研发讨论</li><li>多国语音自动翻译 → 预计 OB 版本加入语音和文字翻译功能</li></ul><h2 id="线下体验赛预告" tabindex="-1">线下体验赛预告 <a class="header-anchor" href="#线下体验赛预告" aria-label="Permalink to &quot;线下体验赛预告&quot;">​</a></h2><p>官方于 10 月 25 日举办线下抢鲜体验赛，邀请玩家亲身感受巅峰对决。</p><p><small>消息来源：巴哈姆特 GNN 整理报导</small></p>',15)])])}const m=e(i,[["render",o]]);export{c as __pageData,m as default};
